# skeptic-1 (wht44/ideas), 16 Oct 2026. Exact-ish linear algebra in the relaxations used by D1's "first decisive test".
#
# (1) Depth seen by a relaxation: the least d with rho(K) in rho(C_d), C_d = span of words with at most d paid letters
#     (free letters P0 arbitrary). In a basis adapted to P0-types, rho(C[P0]) = sum_tau End(tau) (x) I_slots, and the
#     (tau2 <- tau1) component of the bimodule generated by X is Hom(tau1,tau2) (x) (row space of X's slot pattern), so
#     membership reduces to tiny pattern spaces. Calibration: the frame module 1 + 15 + 35 + 84 must need depth 3.
# (2) Cuts (P0-invariant subspaces) of single irreducibles: cap for h, demands for K and for the two-row target K2.
#     Calibration: the hook {28} of V56 must give (10, 18, 28); Theorem M's 105a certificate (20, 38, 49).
# (3) Which tight shapes the cuts refuse: 5 in 14, and the Theorem-T-excluded tight mixed shapes 4+1 in 13, 3+2 in 12,
#     2+3 in 11, 1+4 in 10 (W_K full + W_R two-row in M).
# Matrices: a2-gct's irreps_small.npz (irreducibles of Sp(6,2) restricted to generators of P0, h, K2, K).
import sys, itertools
import numpy as np
np.seterr(all='ignore')   # Accelerate's matmul raises spurious FP flags on this Mac; results are checked for finiteness

import os
NPZ = os.environ.get('IRREPS_NPZ', os.path.join(os.path.dirname(os.path.abspath(__file__)),
                   '..', '..', 'data', 'skeptic-tight-block3-family', 'irreps_small.npz'))
D = np.load(NPZ)


def levi_words():
    g1 = np.array([[1, 1, 0], [0, 1, 0], [0, 0, 1]]); g2 = np.array([[0, 0, 1], [1, 0, 0], [0, 1, 0]])
    seen = {np.eye(3, dtype=int).tobytes(): ()}; fr = [(np.eye(3, dtype=int), ())]
    while fr:
        nx = []
        for M, w in fr:
            for gi, g in enumerate((g1, g2)):
                N = (g @ M) % 2; kk = N.tobytes()
                if kk not in seen: seen[kk] = w + (gi,); nx.append((N, w + (gi,)))
        fr = nx
    return list(seen.values())


WORDS = sorted(levi_words(), key=len)
assert len(WORDS) == 168


def gens(j):
    if j == 0:   # the trivial irreducible
        one = np.ones((1, 1))
        return [one] * 6, [one] * 2, [one] * 3
    return list(D[f'irr{j}_A']), list(D[f'irr{j}_L']), list(D[f'irr{j}_H'])


def piece_elems(p):
    A = p['A']; L = p['L']; dt = A[0].shape[0]
    Ael = []
    for bits in range(64):
        M = np.eye(dt)
        for i in range(6):
            if bits >> i & 1: M = M @ A[i]
        Ael.append(M)
    Lel = {(): np.eye(dt)}
    for w in WORDS:
        if w: Lel[w] = L[w[-1]] @ Lel[w[:-1]]
    return Ael, list(Lel.values())


def commutant_dim(p, rng, ntr=4):
    Ael, Lel = piece_elems(p); dt = Ael[0].shape[0]
    vs = []
    for _ in range(ntr):
        X = rng.standard_normal((dt, dt))
        XL = sum(M @ X @ M.T for M in Lel) / 168; XA = sum(M @ XL @ M.T for M in Ael) / 64
        vs.append(XA.ravel())
    s = np.linalg.svd(np.array(vs), compute_uv=False)
    assert np.all(np.isfinite(s))
    return int((s > 1e-8 * s[0]).sum())


def load(js, seed=12345):
    rng = np.random.default_rng(seed)
    blocks = []; off = 0; allpieces = []; Hs = []
    for j in js:
        A, L, H = gens(j)
        d = A[0].shape[1]
        Ael = []
        for bits in range(64):
            M = np.eye(d)
            for i in range(6):
                if bits >> i & 1: M = M @ A[i]
            Ael.append(M)
        Lel = {(): np.eye(d)}
        for w in WORDS:
            if w: Lel[w] = L[w[-1]] @ Lel[w[:-1]]
        Lel = list(Lel.values())
        S = rng.standard_normal((d, d)); S = S + S.T
        SL = sum(M @ S @ M.T for M in Lel) / 168; R = sum(M @ SL @ M.T for M in Ael) / 64
        w, V = np.linalg.eigh(R)
        cl = []; st = 0
        for i in range(1, d + 1):
            if i == d or w[i] - w[i - 1] > 1e-7 * max(1, abs(w).max()): cl.append((st, i)); st = i
        tests = [A[0], A[3], A[0] @ A[1], A[0] @ A[1] @ A[2], A[3] @ A[5], L[0], L[1], L[0] @ L[1],
                 L[1] @ L[1] @ L[0], A[0] @ L[1], A[3] @ L[0], A[2] @ A[4] @ L[1] @ L[0]]
        for (a, b) in cl:
            Q = V[:, a:b]
            sig = (b - a,) + tuple(round(float(np.trace(Q.T @ T @ Q)), 4) + 0.0 for T in tests)
            allpieces.append(dict(sig=sig, j=j, off=off, Q=Q, A=[Q.T @ x @ Q for x in A], L=[Q.T @ x @ Q for x in L]))
        Hs.append(H); blocks.append((off, d)); off += d
    n = off
    types = {}
    for p in allpieces: types.setdefault(p['sig'], []).append(p)
    Qg = np.zeros((n, n)); col = 0; tlist = []
    for sig in sorted(types, key=lambda s: (s[0], s)):
        ps = types[sig]; dt = sig[0]; ref = ps[0]; slots = []
        # commutant dimension of the reference piece (1 = real type; 2 = complex type would break End(tau) = M_d(R)):
        # rank of P0-averages of random non-symmetric matrices (average over the Levi words, then the 64 unipotents)
        cdim = commutant_dim(ref, rng)
        for p in ps:
            if p is ref: X = np.eye(dt)
            else:
                eqs = [np.kron(np.eye(dt), ga.T) - np.kron(gb, np.eye(dt)) for ga, gb in zip(ref['A'] + ref['L'], p['A'] + p['L'])]
                Mq = np.vstack(eqs); _, sv2, vt = np.linalg.svd(Mq)
                assert sv2[-1] < 1e-8 and (len(sv2) < 2 or sv2[-2] > 1e-6), ('intertwiner', sig, sv2[-3:])
                X = vt[-1].reshape(dt, dt); X = X / np.sqrt(np.trace(X @ X.T) / dt)
                assert np.allclose(X @ X.T, np.eye(dt), atol=1e-8)
            Qp = np.zeros((n, dt)); Qp[p['off']:p['off'] + p['Q'].shape[0], :] = p['Q'] @ X
            Qg[:, col:col + dt] = Qp; slots.append(np.arange(col, col + dt)); col += dt
        tlist.append(dict(d=dt, slots=slots, js=[p['j'] for p in ps], cdim=cdim))
    assert col == n and np.allclose(Qg.T @ Qg, np.eye(n), atol=1e-8)
    mats = []
    for idx in range(3):
        Bm = np.zeros((n, n))
        for (o, d), H in zip(blocks, Hs): Bm[o:o + d, o:o + d] = H[idx]
        mats.append(Qg.T @ Bm @ Qg)
    h, k2, k = mats
    for X in (h, k2, k): assert np.all(np.isfinite(X)) and np.allclose(X @ X.T, np.eye(n), atol=1e-8)
    # the free generators in the adapted basis (to check the block structure)
    return n, h, k, k2, tlist


def rowspace(Z, tol=1e-9):
    if Z.size == 0: return np.zeros((0, Z.shape[1]))
    u, s, vt = np.linalg.svd(Z, full_matrices=False)
    r = int((s > tol * max(1.0, s[0] if len(s) else 1.0)).sum())
    return vt[:r]


def pattern(X, T, t2, t1):
    s2 = T[t2]['slots']; s1 = T[t1]['slots']
    cols = [X[np.ix_(a, b)].ravel() for a in s2 for b in s1]
    Z = np.array(cols).T          # (d2*d1) x (m2*m1)
    return rowspace(Z)


def joint(R1, R2):
    if R1.shape[0] == 0: return R2
    if R2.shape[0] == 0: return R1
    return rowspace(np.vstack([R1, R2]))


def contained(Rsmall, Rbig, tol=1e-7):
    if Rsmall.shape[0] == 0: return True
    if Rbig.shape[0] == 0: return False
    P = Rbig.T @ Rbig
    return np.linalg.norm(Rsmall - Rsmall @ P) < tol * max(1.0, np.linalg.norm(Rsmall))


def rand_free(n, T, rng):
    S = np.zeros((n, n))
    for t in T:
        blk = rng.standard_normal((t['d'], t['d']))
        for s in t['slots']: S[np.ix_(s, s)] = blk
    return S


def depth_table(js, label, rng, ntr=4):
    n, h, k, k2, T = load(js)
    nt = len(T)
    print(f'== {label}: irreps {js}, n={n}, types (dim x mult) = {[(t["d"], len(t["slots"])) for t in T]}, '
          f'commutant dims of the types = {[t["cdim"] for t in T]}')
    # words with <= d paid letters: X_0 = {I}, X_d = {h a_1 h a_2 ... h} sampled with random free a's
    words = {0: [np.eye(n)]}
    words[1] = [h]
    words[2] = [h @ rand_free(n, T, rng) @ h for _ in range(ntr)]
    words[3] = [h @ rand_free(n, T, rng) @ h @ rand_free(n, T, rng) @ h for _ in range(ntr)]
    res = {}
    for name, X in (('K', k), ('K2', k2)):
        need = 0
        for t2 in range(nt):
            for t1 in range(nt):
                PX = pattern(X, T, t2, t1)
                if PX.shape[0] == 0: continue
                R = np.zeros((0, len(T[t2]['slots']) * len(T[t1]['slots'])))
                found = None
                for d in range(0, 4):
                    for Wd in words[d]: R = joint(R, pattern(Wd, T, t2, t1))
                    if contained(PX, R): found = d; break
                if found is None: found = 99
                need = max(need, found)
        res[name] = need
    full = {}
    for d in range(4):
        tot = 0; mx = 0
        for t2 in range(nt):
            for t1 in range(nt):
                R = np.zeros((0, len(T[t2]['slots']) * len(T[t1]['slots'])))
                for dd in range(d + 1):
                    for Wd in words[dd]: R = joint(R, pattern(Wd, T, t2, t1))
                tot += R.shape[0] * T[t2]['d'] * T[t1]['d']
                mx += len(T[t2]['slots']) * len(T[t1]['slots']) * T[t2]['d'] * T[t1]['d']
        full[d] = (tot, mx)
    print(f'   least depth with rho(K) in rho(C_d): {res["K"]};  two-row target K2: {res["K2"]};  '
          f'dim rho(C_d) in the relaxation algebra, d = 0..3: {[full[d][0] for d in range(4)]} of {full[0][1]} (ambient '
          f'incl. cross-irreducible blocks)')
    return n, h, k, k2, T


def subspace_dim(B):
    if B.shape[1] == 0: return 0
    s = np.linalg.svd(B, compute_uv=False)
    return int((s > 1e-8 * max(1.0, s[0])).sum())


def cuts(js, label):
    n, h, k, k2, T = load(js)
    assert all(len(t['slots']) == 1 for t in T), 'multiplicity-free only'
    nt = len(T)
    print(f'== cuts of {label} (types {[t["d"] for t in T]})')
    rows = []
    for mask in range(1, 2 ** nt):
        idx = np.concatenate([T[i]['slots'][0] for i in range(nt) if mask >> i & 1])
        Y = np.eye(n)[:, idx]; dy = Y.shape[1]
        cap = subspace_dim(np.hstack([Y, h @ Y])) - dy
        dK = subspace_dim(np.hstack([Y, k.T @ Y])) - dy
        dR = subspace_dim(np.hstack([Y, k2.T @ Y])) - dy
        names = '+'.join(str(T[i]['d']) for i in range(nt) if mask >> i & 1)
        rows.append((names, dy, cap, dR, dK))
    for r in rows:
        ratio = (r[4] / r[2]) if r[2] else float('inf')
        print(f'   Y = {r[0]:>14s}  dim {r[1]:3d}  cap {r[2]:3d}  two-row demand {r[3]:3d}  full demand {r[4]:3d}  '
              f'(full/cap = {ratio:.4f})')
    return rows


def refuse(rows, WK, WR, M):
    best = None
    for (names, dy, cap, dR, dK) in rows:
        if cap == 0:
            if WK * dK + WR * dR > 0: return (names, 'cap 0')
            continue
        slack = M * cap - (WK * dK + WR * dR)
        if best is None or slack < best[1]: best = (names, slack, cap, dR, dK)
    return best


def main():
    rng = np.random.default_rng(7)
    which = sys.argv[1] if len(sys.argv) > 1 else 'all'
    if which in ('all', 'depth'):
        # calibration: the frame module 1 + 15 + 35 + 84 (the irreducibles with a P0-fixed vector) must need depth 3
        for js, lab in (([0, 2, 6, 10], 'frame-candidate 1+15+35(6)+84'), ([0, 2, 7, 10], 'frame-candidate 1+15+35(7)+84')):
            depth_table(js, lab, rng)
        for j in range(1, 14):
            depth_table([j], f'irr{j}', rng)
        depth_table([8, 11], 'coupled 56+105a (a2-gct)', rng)
        depth_table([8, 9], 'coupled 56+70', rng)
    if which in ('all', 'cuts'):
        shapes = [(5, 0, 14), (4, 1, 13), (3, 2, 12), (2, 3, 11), (1, 4, 10), (5, 0, 13), (1, 4, 9), (1, 4, 11)]
        for j, lab in ((8, 'V56 (irr8)'), (11, 'V105a (irr11)'), (12, 'V105 (irr12)'), (13, 'V105 (irr13)')):
            try:
                rows = cuts([j], lab)
            except AssertionError as e:
                print('   skipped:', e); continue
            for (WK, WR, M) in shapes:
                b = refuse(rows, WK, WR, M)
                print(f'   {WK}+{WR} in {M}: tightest cut {b[0]} slack {b[1]} '
                      f'{"REFUSED" if b[1] < 0 else "allowed"}')


if __name__ == '__main__':
    main()
